begin;
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
create table public.app_users(id uuid primary key references auth.users(id), email text not null unique, name text not null, role text not null check(role in ('Super Admin','Finance','Supervisor','Kasir')), active boolean not null default false, created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(), sku text not null unique, barcode text unique, name text not null check(length(name) between 1 and 160), category text not null default 'Umum', unit text not null default 'pcs', price numeric(18,2) not null check(price>0), cost numeric(20,6) not null check(cost>=0), stock integer not null default 0 check(stock>=0), minimum integer not null default 10 check(minimum>=0), active boolean not null default true);
create table public.shifts(id uuid primary key default gen_random_uuid(), cashier_id uuid not null references public.app_users(id), opened_at timestamptz not null default now(), opening_cash numeric(18,2) not null check(opening_cash>=0), closed_at timestamptz, expected_cash numeric(18,2), counted_cash numeric(18,2), difference numeric(18,2), close_note text, verified_by uuid references public.app_users(id), verified_at timestamptz);
create unique index one_open_drawer on public.shifts((true)) where closed_at is null;
create table public.sales(id uuid primary key, receipt_no bigint generated always as identity unique, shift_id uuid not null references public.shifts(id), cashier_id uuid not null references public.app_users(id), created_at timestamptz not null default now(), total numeric(18,2) not null check(total>0), method text not null check(method in ('Tunai','Transfer','QRIS')), tendered numeric(18,2), change_due numeric(18,2) not null default 0, reference text, verified_by uuid references public.app_users(id), verified_at timestamptz);
create table public.sale_items(sale_id uuid not null references public.sales(id), product_id uuid not null references public.products(id), name text not null, sku text not null, qty integer not null check(qty>0), price numeric(18,2) not null, cost numeric(20,6) not null, primary key(sale_id,product_id));
create table public.purchases(id uuid primary key, vendor text not null, invoice text not null, created_at timestamptz not null default now(), actor_id uuid not null references public.app_users(id), product_id uuid not null references public.products(id), qty integer not null check(qty>0), unit_cost numeric(18,2) not null check(unit_cost>=0), extra numeric(18,2) not null default 0 check(extra>=0), total numeric(18,2) not null, source text not null check(source in ('Kas laci','Dana luar laci')), unique(vendor,invoice,product_id));
create table public.cash_moves(id uuid primary key, shift_id uuid not null references public.shifts(id), actor_id uuid not null references public.app_users(id), amount numeric(18,2) not null check(amount<>0), kind text not null, note text not null check(length(note)>=3), created_at timestamptz not null default now());
create table public.stock_moves(id bigint generated always as identity primary key, product_id uuid not null references public.products(id), actor_id uuid not null references public.app_users(id), delta integer not null, kind text not null, reference uuid, reason text not null, created_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key, actor_id uuid references public.app_users(id), action text not null, detail jsonb not null, created_at timestamptz not null default now());
create index sales_shift_idx on public.sales(shift_id);create index sales_cashier_idx on public.sales(cashier_id);create index shifts_cashier_idx on public.shifts(cashier_id);create index purchases_product_idx on public.purchases(product_id);create index moves_shift_idx on public.cash_moves(shift_id);create index stock_product_idx on public.stock_moves(product_id);
do $$ declare t text;begin foreach t in array array['app_users','products','shifts','sales','sale_items','purchases','cash_moves','stock_moves','audit_log'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end $$;
-- All data access goes through checked RPC functions. Tables intentionally have no direct client grants or policies.
create function private.require_role(allowed text[]) returns text language plpgsql security definer set search_path='' as $$ declare r text;begin select role into r from public.app_users where id=auth.uid() and active; if r is null or not(r=any(allowed)) then raise exception 'Akses ditolak atau akun belum diaktifkan';end if; return r;end $$;
create function private.log_action(a text,d jsonb) returns void language sql security definer set search_path='' as $$ insert into public.audit_log(actor_id,action,detail) values(auth.uid(),a,d) $$;
create function private.on_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.app_users(id,email,name,role,active) values(new.id,lower(new.email),split_part(new.email,'@',1),case when lower(new.email)='appkasir.larisindo@gmail.com' then 'Super Admin' else 'Kasir' end,lower(new.email)='appkasir.larisindo@gmail.com');return new;end $$;
create trigger pos_signup after insert on auth.users for each row execute function private.on_signup();
create function public.pos_snapshot() returns jsonb language plpgsql security definer set search_path='' as $$ declare r text;u uuid:=auth.uid();begin r:=private.require_role(array['Super Admin','Finance','Supervisor','Kasir']);return jsonb_build_object(
 'me',(select to_jsonb(x) from public.app_users x where id=u),
 'products',coalesce((select jsonb_agg(case when r='Kasir' then to_jsonb(p)-'cost' else to_jsonb(p) end order by p.name) from public.products p where active),'[]'::jsonb),
 'users',coalesce((select jsonb_agg(to_jsonb(x) order by name) from public.app_users x where r='Super Admin' or id=u),'[]'::jsonb),
 'shifts',coalesce((select jsonb_agg(to_jsonb(x) order by opened_at desc) from public.shifts x where r<>'Kasir' or cashier_id=u),'[]'::jsonb),
 'sales',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('items',coalesce((select jsonb_agg(case when r='Kasir' then to_jsonb(i)-'cost' else to_jsonb(i) end) from public.sale_items i where sale_id=x.id),'[]'::jsonb)) order by created_at desc) from public.sales x where r<>'Kasir' or cashier_id=u),'[]'::jsonb),
 'purchases',case when r='Kasir' then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(x) order by created_at desc) from public.purchases x),'[]'::jsonb) end,
 'cash_moves',coalesce((select jsonb_agg(to_jsonb(x) order by created_at desc) from public.cash_moves x where r<>'Kasir' or actor_id=u),'[]'::jsonb),
 'stock_moves',case when r='Kasir' then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(x) order by created_at desc) from public.stock_moves x),'[]'::jsonb) end,
 'audit',case when r='Kasir' then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(x)) from (select * from public.audit_log order by id desc limit 200) x),'[]'::jsonb) end);end $$;
create function public.pos_user(p_id uuid,p_role text,p_active boolean,p_name text) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_role(array['Super Admin']);perform pg_advisory_xact_lock(241013);
 if p_role not in ('Super Admin','Finance','Supervisor','Kasir') or p_active is null or length(trim(p_name)) not between 1 and 100 then raise exception 'Data pengguna tidak valid';end if;
 if p_id=auth.uid() and (not p_active or p_role<>'Super Admin') then raise exception 'Tidak dapat menurunkan akses akun sendiri';end if;
 if exists(select 1 from public.app_users where id=p_id and role='Super Admin' and active) and (p_role<>'Super Admin' or not p_active) and (select count(*) from public.app_users where active and role='Super Admin')<=1 then raise exception 'Minimal satu Super Admin aktif';end if;
 update public.app_users set role=p_role,active=p_active,name=trim(p_name) where id=p_id;if not found then raise exception 'Pengguna tidak ditemukan';end if;perform private.log_action('user_access',jsonb_build_object('user_id',p_id,'role',p_role,'active',p_active));end $$;
create function public.pos_product(p_id uuid,p_sku text,p_barcode text,p_name text,p_category text,p_unit text,p_price numeric,p_cost numeric,p_minimum integer) returns uuid language plpgsql security definer set search_path='' as $$ declare k uuid:=coalesce(p_id,gen_random_uuid());begin perform private.require_role(array['Super Admin','Supervisor']);
 if p_price is null or p_price<=0 or p_price>1000000000 or p_cost is null or p_cost<0 or p_cost>1000000000 or p_minimum is null or p_minimum<0 or length(trim(p_sku)) not between 1 and 80 or length(trim(p_name)) not between 1 and 160 or length(trim(p_unit)) not between 1 and 30 then raise exception 'Data barang tidak valid';end if;
 if p_id is null then insert into public.products(id,sku,barcode,name,category,unit,price,cost,minimum) values(k,trim(p_sku),nullif(trim(p_barcode),''),trim(p_name),trim(p_category),trim(p_unit),p_price,p_cost,p_minimum);
 else update public.products set sku=trim(p_sku),barcode=nullif(trim(p_barcode),''),name=trim(p_name),category=trim(p_category),unit=trim(p_unit),price=p_price,minimum=p_minimum where id=k and active;if not found then raise exception 'Barang tidak ditemukan';end if;end if;
 perform private.log_action('product_saved',jsonb_build_object('id',k,'sku',p_sku,'price',p_price));return k;end $$;
create function public.pos_open_shift(p_id uuid,p_opening numeric) returns uuid language plpgsql security definer set search_path='' as $$ declare s public.shifts;begin perform private.require_role(array['Super Admin','Kasir']);if p_opening is null or p_opening<0 or p_opening>1000000000 then raise exception 'Modal tidak valid';end if;
 select * into s from public.shifts where id=p_id;if found then if s.cashier_id<>auth.uid() then raise exception 'ID tidak valid';end if;return s.id;end if;
 insert into public.shifts(id,cashier_id,opening_cash) values(p_id,auth.uid(),p_opening);perform private.log_action('shift_open',jsonb_build_object('id',p_id,'opening',p_opening));return p_id;end $$;
create function public.pos_checkout(p_id uuid,p_shift uuid,p_items jsonb,p_method text,p_tendered numeric,p_reference text) returns uuid language plpgsql security definer set search_path='' as $$ declare s public.shifts; p public.products; j jsonb;q integer;total numeric:=0; existing public.sales;begin
 perform private.require_role(array['Super Admin','Kasir']);
 select * into s from public.shifts where id=p_shift for update;if not found or s.cashier_id<>auth.uid() then raise exception 'Shift bukan milik pengguna';end if;
 select * into existing from public.sales where id=p_id;if found then if existing.cashier_id<>auth.uid() or existing.shift_id<>p_shift then raise exception 'ID transaksi tidak valid';end if;return existing.id;end if;
 if s.closed_at is not null then raise exception 'Shift telah ditutup';end if;
 if p_method is null or p_method not in ('Tunai','Transfer','QRIS') or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 100 then raise exception 'Transaksi tidak valid';end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(p_items)x)<>jsonb_array_length(p_items) then raise exception 'Barang duplikat';end if;
 for j in select x from jsonb_array_elements(p_items)x order by x->>'id' loop
 if (j->>'qty') is null or (j->>'qty')!~'^[1-9][0-9]{0,5}$' then raise exception 'Jumlah barang tidak valid';end if;q:=(j->>'qty')::integer;
 select * into p from public.products where id=(j->>'id')::uuid and active for update;if not found or p.stock<q then raise exception 'Barang tidak tersedia atau stok tidak cukup';end if;total:=total+p.price*q;end loop;
 if p_method='Tunai' and (p_tendered is null or p_tendered<total or p_tendered>1000000000) then raise exception 'Uang diterima kurang atau tidak valid';end if;
 if p_method<>'Tunai' and length(trim(coalesce(p_reference,'')))<3 then raise exception 'Isi referensi pembayaran';end if;
 insert into public.sales(id,shift_id,cashier_id,total,method,tendered,change_due,reference) values(p_id,p_shift,auth.uid(),total,p_method,case when p_method='Tunai' then p_tendered end,case when p_method='Tunai' then p_tendered-total else 0 end,nullif(trim(p_reference),''));
 for j in select x from jsonb_array_elements(p_items)x loop q:=(j->>'qty')::integer;select * into p from public.products where id=(j->>'id')::uuid;insert into public.sale_items values(p_id,p.id,p.name,p.sku,q,p.price,p.cost);update public.products set stock=stock-q where id=p.id;insert into public.stock_moves(product_id,actor_id,delta,kind,reference,reason) values(p.id,auth.uid(),-q,'Penjualan',p_id,'Penjualan POS');end loop;
 perform private.log_action('sale',jsonb_build_object('id',p_id,'total',total,'method',p_method));return p_id;end $$;
create function public.pos_cash_move(p_id uuid,p_shift uuid,p_amount numeric,p_kind text,p_note text) returns uuid language plpgsql security definer set search_path='' as $$ declare s public.shifts;r text;begin r:=private.require_role(array['Super Admin','Finance','Kasir']);select * into s from public.shifts where id=p_shift for update;if not found or s.closed_at is not null or (r='Kasir' and s.cashier_id<>auth.uid()) then raise exception 'Shift tidak tersedia';end if;
 if p_amount is null or p_amount=0 or abs(p_amount)>1000000000 or length(trim(p_note))<3 or p_kind not in ('Setoran keluar','Pengeluaran','Penerimaan lain') then raise exception 'Mutasi tidak valid';end if;
 if (p_kind='Penerimaan lain' and p_amount<0) or (p_kind<>'Penerimaan lain' and p_amount>0) then raise exception 'Arah mutasi salah';end if;
 if exists(select 1 from public.cash_moves where id=p_id) then return p_id;end if;insert into public.cash_moves values(p_id,p_shift,auth.uid(),p_amount,p_kind,trim(p_note),now());perform private.log_action('cash_move',jsonb_build_object('id',p_id,'amount',p_amount,'note',p_note));return p_id;end $$;
create function public.pos_close_shift(p_id uuid,p_counted numeric,p_note text) returns void language plpgsql security definer set search_path='' as $$ declare s public.shifts;e numeric;begin perform private.require_role(array['Super Admin','Kasir']);select * into s from public.shifts where id=p_id for update;if not found or s.cashier_id<>auth.uid() then raise exception 'Shift bukan milik pengguna';end if;if s.closed_at is not null then return;end if;
 if p_counted is null or p_counted<0 or p_counted>1000000000 then raise exception 'Kas fisik tidak valid';end if;
 select s.opening_cash+coalesce((select sum(total) from public.sales where shift_id=p_id and method='Tunai'),0)+coalesce((select sum(amount) from public.cash_moves where shift_id=p_id),0) into e;
 if p_counted<>e and length(trim(coalesce(p_note,'')))<3 then raise exception 'Catatan selisih wajib diisi';end if;
 update public.shifts set closed_at=now(),expected_cash=e,counted_cash=p_counted,difference=p_counted-e,close_note=p_note where id=p_id;perform private.log_action('shift_close',jsonb_build_object('id',p_id,'expected',e,'counted',p_counted,'difference',p_counted-e));end $$;
create function public.pos_verify(p_kind text,p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_role(array['Super Admin','Finance']);if p_kind='sale' then update public.sales set verified_by=auth.uid(),verified_at=now() where id=p_id and method<>'Tunai' and verified_at is null;elsif p_kind='shift' then update public.shifts set verified_by=auth.uid(),verified_at=now() where id=p_id and closed_at is not null and verified_at is null;else raise exception 'Jenis tidak valid';end if;if not found then raise exception 'Tidak ada data yang perlu diverifikasi';end if;perform private.log_action('verified',jsonb_build_object('kind',p_kind,'id',p_id));end $$;
create function public.pos_receive(p_id uuid,p_product uuid,p_qty integer,p_cost numeric,p_extra numeric,p_vendor text,p_invoice text,p_source text,p_shift uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare p public.products;s public.shifts;t numeric;begin perform private.require_role(array['Super Admin','Supervisor']);
 -- Lock drawer before product, same order as checkout, to avoid deadlocks.
 if p_source='Kas laci' then select * into s from public.shifts where id=p_shift for update;if not found or s.closed_at is not null then raise exception 'Pilih shift aktif';end if;end if;
 select * into p from public.products where id=p_product and active for update;if not found then raise exception 'Barang tidak ditemukan';end if;
 if exists(select 1 from public.purchases where id=p_id) then return p_id;end if;
 if p_qty is null or p_qty not between 1 and 999999 or p_cost is null or p_cost<0 or p_cost>1000000000 or p_extra is null or p_extra<0 or p_extra>1000000000 or length(trim(p_vendor))<1 or length(trim(p_invoice))<1 or p_source is null or p_source not in ('Kas laci','Dana luar laci') then raise exception 'Data pembelian tidak valid';end if;
 t:=p_qty*(p_cost+p_extra);insert into public.purchases values(p_id,trim(p_vendor),trim(p_invoice),now(),auth.uid(),p_product,p_qty,p_cost,p_extra,t,p_source);
 update public.products set cost=(stock*cost+t)/(stock+p_qty),stock=stock+p_qty where id=p_product;
 insert into public.stock_moves(product_id,actor_id,delta,kind,reference,reason) values(p_product,auth.uid(),p_qty,'Pembelian',p_id,p_vendor||' / '||p_invoice);
 if p_source='Kas laci' and t>0 then insert into public.cash_moves values(p_id,p_shift,auth.uid(),-t,'Pembelian',p_vendor||' / '||p_invoice,now());end if;
 perform private.log_action('purchase_received',jsonb_build_object('id',p_id,'total',t,'source',p_source));return p_id;end $$;
create function public.pos_adjust(p_id uuid,p_stock integer,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare p public.products;begin perform private.require_role(array['Super Admin','Supervisor']);select * into p from public.products where id=p_id for update;if not found or p_stock is null or p_stock<0 or length(trim(coalesce(p_reason,'')))<5 then raise exception 'Stok atau alasan tidak valid';end if;update public.products set stock=p_stock where id=p_id;insert into public.stock_moves(product_id,actor_id,delta,kind,reason) values(p_id,auth.uid(),p_stock-p.stock,'Opname',trim(p_reason));perform private.log_action('stock_adjusted',jsonb_build_object('id',p_id,'before',p.stock,'after',p_stock,'reason',p_reason));end $$;
revoke all on all functions in schema private from public,anon,authenticated;
revoke all on all functions in schema public from public,anon,authenticated;
grant execute on function public.pos_snapshot(),public.pos_user(uuid,text,boolean,text),public.pos_product(uuid,text,text,text,text,text,numeric,numeric,integer),public.pos_open_shift(uuid,numeric),public.pos_checkout(uuid,uuid,jsonb,text,numeric,text),public.pos_cash_move(uuid,uuid,numeric,text,text),public.pos_close_shift(uuid,numeric,text),public.pos_verify(text,uuid),public.pos_receive(uuid,uuid,integer,numeric,numeric,text,text,text,uuid),public.pos_adjust(uuid,integer,text) to authenticated;
commit;
